    { const char * tb_v250 = "TB_API volatile unsigned short *const tb_vga = (volatile unsigned short *)0xB8000;\n"; *(const char * *)tb_grow(v_lines) = tb_v250; }
    { const char * tb_v251 = "TB_API int tb_vrow = 0, tb_vcol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v251; }
