    { const char * tb_v1097 = "TB_COLD TB_API void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1097; }
    { const char * tb_v1098 = "    fflush(stdout);\n"; *(const char * *)tb_grow(v_lines) = tb_v1098; }
