    { const char * tb_v1140 = "    if (lim == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1140; }
    { const char * tb_v1141 = "        lim = 8LL << 20;\n"; *(const char * *)tb_grow(v_lines) = tb_v1141; }
