    { const char * tb_v1160 = "    tb_stack_lim = lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v1160; }
    { const char * tb_v1161 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1161; }
    { const char * tb_v1162 = "// поток background или ядра: сначала ставим защиту стека, потом сама работа\n"; *(const char * *)tb_grow(v_lines) = tb_v1162; }
    { const char * tb_v1163 = "// сколько потоков background / ядер работает сейчас: уборка памяти ждёт, пока их нет\n"; *(const char * *)tb_grow(v_lines) = tb_v1163; }
    { const char * tb_v1164 = "TB_API int tb_gthreads = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1164; }
    { const char * tb_v1165 = "// короткое ожидание без сна (подсказка процессору)\n"; *(const char * *)tb_grow(v_lines) = tb_v1165; }
    { const char * tb_v1166 = "#if defined(__x86_64__) || defined(__i386__)\n"; *(const char * *)tb_grow(v_lines) = tb_v1166; }
    { const char * tb_v1167 = "#define __builtin_ia32_pause_or_yield() __builtin_ia32_pause()\n"; *(const char * *)tb_grow(v_lines) = tb_v1167; }
    { const char * tb_v1168 = "#elif defined(__aarch64__)\n"; *(const char * *)tb_grow(v_lines) = tb_v1168; }
