    { const char * tb_v1340 = "    while (tb_nchunks > m.n && tb_nchunks > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1340; }
    { const char * tb_v1341 = "        tb_nchunks -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1341; }
