    { const char * tb_v2305 = "// ---------- время и дата ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2305; }
    { const char * tb_v2306 = "TB_API long long tb_unix_time(void) { return (long long)time(0); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2306; }
    { const char * tb_v2307 = "TB_API const char *tb_date_now(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2307; }
    { const char * tb_v2308 = "    time_t t = time(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2308; }
    { const char * tb_v2309 = "    struct tm tmv;\n"; *(const char * *)tb_grow(v_lines) = tb_v2309; }
