    { const char * tb_v2360 = "TB_API const char *tb_js_ws(const char *p) { while (*p == ' ' || *p == '\\n' || *p == '\\r' || *p == '\\t') p++; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2360; }
    { const char * tb_v2361 = "// пропустить одно значение; адрес после него или 0, если JSON сломан\n"; *(const char * *)tb_grow(v_lines) = tb_v2361; }
