    { const char * tb_v2564 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v2564; }
    { const char * tb_v2565 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2565; }
    { const char * tb_v2566 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v2566; }
    { const char * tb_v2567 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2567; }
    { const char * tb_v2568 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v2568; }
    { const char * tb_v2569 = "TB_API unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2569; }
    { const char * tb_v2570 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2570; }
    { const char * tb_v2571 = "    if (d->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2571; }
    { const char * tb_v2572 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2572; }
    { const char * tb_v2573 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2573; }
    { const char * tb_v2574 = "        h ^= (unsigned long long)*(const long long *)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v2574; }
    { const char * tb_v2575 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2575; }
    { const char * tb_v2576 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v2576; }
    { const char * tb_v2577 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2577; }
    { const char * tb_v2578 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v2578; }
    { const char * tb_v2579 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2579; }
    { const char * tb_v2580 = "TB_API int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2580; }
    { const char * tb_v2581 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2581; }
    { const char * tb_v2582 = "    return *(const long long *)a == *(const long long *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v2582; }
