    { const char * tb_v2601 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2601; }
    { const char * tb_v2602 = "        i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2602; }
    { const char * tb_v2603 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2603; }
    { const char * tb_v2604 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2604; }
    { const char * tb_v2605 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2605; }
    { const char * tb_v2606 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v2606; }
