    { const char * tb_v2608 = "    if (old && !(tb_nchunks > 0 && tb_in_temp(old))) tb_gc_free(old);\n"; *(const char * *)tb_grow(v_lines) = tb_v2608; }
    { const char * tb_v2609 = "    void *p = tb_in_cur_temp(d->keys->data) ? tb_temp_alloc(bytes) : tb_gc_alloc_np(bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v2609; }
    { const char * tb_v2610 = "    if (!p) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2610; }
    { const char * tb_v2611 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2611; }
    { const char * tb_v2612 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2612; }
    { const char * tb_v2613 = "TB_API void tb_dreindex(tb_dict *d, long long nslots) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2613; }
    { const char * tb_v2614 = "    d->mode = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2614; }
    { const char * tb_v2615 = "    if (d->pos) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2615; }
    { const char * tb_v2616 = "        if (!(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v2616; }
    { const char * tb_v2617 = "        d->pos = 0; d->npos = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2617; }
    { const char * tb_v2618 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2618; }
    { const char * tb_v2619 = "    d->nslots = nslots;\n"; *(const char * *)tb_grow(v_lines) = tb_v2619; }
    { const char * tb_v2620 = "    d->slots = tb_dalloc(d, d->slots, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2620; }
    { const char * tb_v2621 = "    memset(d->slots, 0, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2621; }
