    { const char * tb_v2810 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2810; }
    { const char * tb_v2811 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2811; }
    { const char * tb_v2812 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2812; }
    { const char * tb_v2813 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2813; }
    { const char * tb_v2814 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2814; }
    { const char * tb_v2815 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v2815; }
    { const char * tb_v2816 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2816; }
    { const char * tb_v2817 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2817; }
    { const char * tb_v2818 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2818; }
    { const char * tb_v2819 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v2819; }
    { const char * tb_v2820 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v2820; }
    { const char * tb_v2821 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v2821; }
    { const char * tb_v2822 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2822; }
    { const char * tb_v2823 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2823; }
    { const char * tb_v2824 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v2824; }
    { const char * tb_v2825 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v2825; }
    { const char * tb_v2826 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2826; }
    { const char * tb_v2827 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2827; }
    { const char * tb_v2828 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2828; }
    { const char * tb_v2829 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2829; }
    { const char * tb_v2830 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v2830; }
    { const char * tb_v2831 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v2831; }
    { const char * tb_v2832 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2832; }
    { const char * tb_v2833 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v2833; }
    { const char * tb_v2834 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2834; }
    { const char * tb_v2835 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2835; }
    { const char * tb_v2836 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2836; }
    { const char * tb_v2837 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2837; }
    { const char * tb_v2838 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2838; }
    { const char * tb_v2839 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2839; }
    { const char * tb_v2840 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v2840; }
    { const char * tb_v2841 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v2841; }
    { const char * tb_v2842 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2842; }
    { const char * tb_v2843 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2843; }
    { const char * tb_v2844 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2844; }
    { const char * tb_v2845 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2845; }
    { const char * tb_v2846 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2846; }
    { const char * tb_v2847 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2847; }
    { const char * tb_v2848 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2848; }
    { const char * tb_v2849 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2849; }
    { const char * tb_v2850 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2850; }
    { const char * tb_v2851 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v2851; }
    { const char * tb_v2852 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2852; }
    { const char * tb_v2853 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2853; }
    { const char * tb_v2854 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2854; }
    { const char * tb_v2855 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v2855; }
    { const char * tb_v2856 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2856; }
    { const char * tb_v2857 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v2857; }
    { const char * tb_v2858 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2858; }
    { const char * tb_v2859 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2859; }
    { const char * tb_v2860 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v2860; }
    { const char * tb_v2861 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v2861; }
    { const char * tb_v2862 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v2862; }
    { const char * tb_v2863 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v2863; }
    { const char * tb_v2864 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2864; }
    { const char * tb_v2865 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v2865; }
    { const char * tb_v2866 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2866; }
    { const char * tb_v2867 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2867; }
    { const char * tb_v2868 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2868; }
    { const char * tb_v2869 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2869; }
    { const char * tb_v2870 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v2870; }
    { const char * tb_v2871 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2871; }
    { const char * tb_v2872 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2872; }
    { const char * tb_v2873 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2873; }
    { const char * tb_v2874 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2874; }
    { const char * tb_v2875 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2875; }
    { const char * tb_v2876 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2876; }
    { const char * tb_v2877 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v2877; }
    { const char * tb_v2878 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v2878; }
    { const char * tb_v2879 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2879; }
    { const char * tb_v2880 = "    if (n == 1) { work(job); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2880; }
    { const char * tb_v2881 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v2881; }
    { const char * tb_v2882 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2882; }
    { const char * tb_v2883 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v2883; }
    { const char * tb_v2884 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2884; }
    { const char * tb_v2885 = "            if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2885; }
    { const char * tb_v2886 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2886; }
    { const char * tb_v2887 = "        for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2887; }
    { const char * tb_v2888 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2888; }
    { const char * tb_v2889 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2889; }
    { const char * tb_v2890 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2890; }
    { const char * tb_v2891 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v2891; }
    { const char * tb_v2892 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2892; }
    { const char * tb_v2893 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v2893; }
    { const char * tb_v2894 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2894; }
    { const char * tb_v2895 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2895; }
    { const char * tb_v2896 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2896; }
    { const char * tb_v2897 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2897; }
    { const char * tb_v2898 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2898; }
    { const char * tb_v2899 = "    __atomic_add_fetch(&tb_gthreads, n - 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v2899; }
    { const char * tb_v2900 = "    __atomic_add_fetch(&tb_pool_gen, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2900; }
    { const char * tb_v2901 = "    pthread_cond_broadcast(&tb_pool_go);\n"; *(const char * *)tb_grow(v_lines) = tb_v2901; }
    { const char * tb_v2902 = "    pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2902; }
    { const char * tb_v2903 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2903; }
    { const char * tb_v2904 = "    if (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2904; }
    { const char * tb_v2905 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2905; }
    { const char * tb_v2906 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v2906; }
    { const char * tb_v2907 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2907; }
    { const char * tb_v2908 = "        while (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) pthread_cond_wait(&tb_pool_end, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2908; }
    { const char * tb_v2909 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2909; }
    { const char * tb_v2910 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2910; }
    { const char * tb_v2911 = "    __atomic_store_n(&tb_pool_busy, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2911; }
    { const char * tb_v2912 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2912; }
    { const char * tb_v2913 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2913; }
    { const char * tb_v2914 = "TB_API long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2914; }
    { const char * tb_v2915 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v2915; }
    { const char * tb_v2916 = "    return s < 1 ? 1 : s;\n"; *(const char * *)tb_grow(v_lines) = tb_v2916; }
    { const char * tb_v2917 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2917; }
    { const char * tb_v2918 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2918; }
    { const char * tb_v2919 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2919; }
    { const char * tb_v2920 = "TB_INL long long tb_band(long long a, long long b) { return a & b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2920; }
    { const char * tb_v2921 = "TB_INL long long tb_bor(long long a, long long b) { return a | b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2921; }
    { const char * tb_v2922 = "TB_INL long long tb_bxor(long long a, long long b) { return a ^ b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2922; }
    { const char * tb_v2923 = "TB_INL long long tb_bnot(long long a) { return ~a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2923; }
    { const char * tb_v2924 = "TB_INL long long tb_shl(long long a, long long n) { return (long long)((unsigned long long)a << (n & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2924; }
    { const char * tb_v2925 = "TB_INL long long tb_shr(long long a, long long n) { return (long long)((unsigned long long)a >> (n & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2925; }
    { const char * tb_v2926 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v2926; }
    { const char * tb_v2927 = "TB_INL long long tb_rd8(long long a) { return *(volatile uint8_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2927; }
    { const char * tb_v2928 = "TB_INL long long tb_rd16(long long a) { return *(volatile uint16_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2928; }
    { const char * tb_v2929 = "TB_INL long long tb_rd32(long long a) { return *(volatile uint32_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2929; }
    { const char * tb_v2930 = "TB_INL long long tb_rd64(long long a) { return (long long)*(volatile uint64_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2930; }
    { const char * tb_v2931 = "TB_INL void tb_wr8(long long a, long long v) { *(volatile uint8_t *)(uintptr_t)a = (uint8_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2931; }
    { const char * tb_v2932 = "TB_INL void tb_wr16(long long a, long long v) { *(volatile uint16_t *)(uintptr_t)a = (uint16_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2932; }
    { const char * tb_v2933 = "TB_INL void tb_wr32(long long a, long long v) { *(volatile uint32_t *)(uintptr_t)a = (uint32_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2933; }
    { const char * tb_v2934 = "TB_INL void tb_wr64(long long a, long long v) { *(volatile uint64_t *)(uintptr_t)a = (uint64_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2934; }
    { const char * tb_v2935 = "TB_INL long long tb_addr_of(tb_list *l) { return (long long)(uintptr_t)l->data; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2935; }
    { const char * tb_v2936 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2936; }
    { const char * tb_v2937 = "TB_INL long long tb_pin8(long long p) { return tb_inb((unsigned short)p); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2937; }
    { const char * tb_v2938 = "TB_INL long long tb_pin16(long long p) { return tb_inw((unsigned short)p); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2938; }
    { const char * tb_v2939 = "TB_INL long long tb_pin32(long long p) { return tb_inl((unsigned short)p); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2939; }
