    { const char * tb_v2941 = "TB_INL void tb_pout16(long long p, long long v) { tb_outw((unsigned short)p, (unsigned short)v); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2941; }
    { const char * tb_v2942 = "TB_INL void tb_pout32(long long p, long long v) { tb_outl((unsigned short)p, (unsigned int)v); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2942; }
    { const char * tb_v2943 = "// замок в ядре: одна команда xchg + прерывания выключены, пока замок у нас\n"; *(const char * *)tb_grow(v_lines) = tb_v2943; }
    { const char * tb_v2944 = "// (так прерывание не застрянет на замке, который держит прерванная задача)\n"; *(const char * *)tb_grow(v_lines) = tb_v2944; }
    { const char * tb_v2945 = "TB_INL unsigned long tb_lock_take(int *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2945; }
    { const char * tb_v2946 = "    uint32_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v2946; }
    { const char * tb_v2947 = "    while (__atomic_exchange_n(l, 1, __ATOMIC_ACQUIRE)) { tb_irq_restore(f); tb_yield(); f = tb_irq_save(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2947; }
    { const char * tb_v2948 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v2948; }
    { const char * tb_v2949 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2949; }
    { const char * tb_v2950 = "TB_INL void tb_lock_give(int *l, unsigned long f) { __atomic_store_n(l, 0, __ATOMIC_RELEASE); tb_irq_restore((uint32_t)f); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2950; }
    { const char * tb_v2951 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2951; }
    { const char * tb_v2952 = "// замок в программе: атомарный обмен; занято — сначала коротко ждём, потом уступаем ядро\n"; *(const char * *)tb_grow(v_lines) = tb_v2952; }
