    { const char * tb_v2967 = "// ---------- канал: очередь между потоками (channel int / text ...) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2967; }
    { const char * tb_v2968 = "// send кладёт в конец (очередь растёт, отправитель не ждёт), receive берёт из начала\n"; *(const char * *)tb_grow(v_lines) = tb_v2968; }
    { const char * tb_v2969 = "// и ждёт, пока что-то придёт. close: больше не пишут; each по каналу кончается,\n"; *(const char * *)tb_grow(v_lines) = tb_v2969; }
    { const char * tb_v2970 = "// когда он закрыт и пуст. Текст копируется: отправитель может удалить свою память.\n"; *(const char * *)tb_grow(v_lines) = tb_v2970; }
    { const char * tb_v2971 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v2971; }
