    { const char * tb_v2975 = "    pthread_mutex_t m; pthread_cond_t cv;\n"; *(const char * *)tb_grow(v_lines) = tb_v2975; }
    { const char * tb_v2976 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2976; }
